export default function LandingPage({ onLoginSuccess }: { onLoginSuccess: () => void }) {
  const [error, setError] = useState("");

  const handleSuccess = async (credentialResponse: any) => {
    setError("");
    try {
      const res = await fetch("http://localhost:8000/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ credential: credentialResponse.credential }),
        credentials: "include",
      });

      if (!res.ok) {
        const data = await res.json();
        setError(data.detail || "Authentication failed. Ensure you are using an authorized @hua.gr email.");
        return;
      }
      onLoginSuccess();
    } catch (err) {
      setError("Network error connecting to the authentication server.");
    }
  };

  return (
    <div className="relative w-full h-screen bg-[#020604] overflow-hidden flex flex-col lg:flex-row font-sans">
      
      {/* 
        NON-SYMMETRICAL BACKGROUND WAVE
        Gradient adjusted to sit perfectly between dark and vibrant emerald greens
      */}
      <svg 
        className="absolute inset-0 w-full h-full pointer-events-none z-0 hidden lg:block" 
        preserveAspectRatio="none" 
        viewBox="0 0 1440 1024"
      >
        <defs>
          <linearGradient id="wave-grad-medium" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#0D9472" />
            <stop offset="100%" stopColor="#03251D" />
          </linearGradient>
        </defs>
        <path d="M0,0 H620 C420,320 980,480 500,1024 H0 V0 Z" fill="url(#wave-grad-medium)" />
      </svg>

      {/* MOBILE BACKGROUND */}
      <div className="absolute inset-0 w-full h-full pointer-events-none z-0 block lg:hidden bg-gradient-to-br from-[#0D9472] to-[#03251D]"></div>

      {/* LEFT SECTION (Text & CTA with clamp fluid responsive proportions) */}
      <div className="relative z-10 w-full lg:w-[50%] h-full flex flex-col px-[clamp(1.5rem,4vw,5rem)] py-[clamp(2rem,4vh,4rem)] text-white">
        
        {/* Top Header / Logo Position */}
        <div className="flex items-center gap-[clamp(0.75rem,1.5vw,1.25rem)] shrink-0">
          <img src="/icon.png" alt="HUA Logo" className="w-[clamp(2.5rem,3.5vw,4rem)] h-[clamp(2.5rem,3.5vw,4rem)] drop-shadow-lg" />
          <span className="text-[clamp(1.25rem,1.8vw,2.25rem)] font-extrabold tracking-widest normal-case text-white">
            HUAssistant
          </span>
        </div>

        {/* Main Hero Content (Moved up via negative margin to align with map top) */}
        <div className="flex-1 flex flex-col justify-center lg:-mt-32 lg:pr-[clamp(1rem,3vw,3rem)]">
          <h1 className="text-[clamp(2.25rem,4vw,4.5rem)] font-bold mb-[clamp(0.75rem,1.5vh,1.5rem)] leading-[1.1] tracking-tight">
            Smart Campus <br /> Assistant
          </h1>
          <p className="text-[clamp(0.875rem,1.1vw,1.25rem)] text-white/90 max-w-[clamp(20rem,30vw,36rem)] mb-[clamp(1.25rem,2.5vh,2.5rem)] leading-relaxed">
            Harokopio University's official Agent for monitoring the Omirou building.
          </p>

          <div className="flex flex-col items-start gap-[clamp(0.75rem,1.5vh,1.25rem)]">
            
            {/* Custom Google Button using fluid clamp sizing */}
            <div className="relative inline-flex items-center justify-center overflow-hidden rounded-full bg-[#1A1A1A]/80 border border-[#333333] px-[clamp(1rem,1.5vw,1.75rem)] py-[clamp(0.5rem,1vh,0.875rem)] text-[clamp(0.8rem,0.9vw,1rem)] font-medium text-[#A3B8B2] hover:text-[#14C89B] hover:bg-[#2A2A2A] transition-colors duration-300 shadow-inner group">
              
              {/* Transparent Google SVG Icon */}
              <svg className="w-[clamp(1rem,1.2vw,1.25rem)] h-[clamp(1rem,1.2vw,1.25rem)] mr-[clamp(0.5rem,0.75vw,0.75rem)] shrink-0" viewBox="0 0 24 24">
                <path
                  fill="#EA4335"
                  d="M12 5c1.6 0 3 .6 4.1 1.6l3.1-3.1C17.3 1.7 14.8 1 12 1 7.5 1 3.7 3.6 1.9 7.3l3.7 2.9C6.5 7.2 9 5 12 5z"
                />
                <path
                  fill="#4285F4"
                  d="M23.5 12.3c0-.8-.1-1.6-.2-2.3H12v4.5h6.5c-.3 1.5-1.1 2.8-2.4 3.7l3.7 2.9c2.2-2 3.7-5 3.7-8.8z"
                />
                <path
                  fill="#FBBC05"
                  d="M5.6 14.8c-.2-.7-.4-1.5-.4-2.8s.2-2.1.4-2.8L1.9 6.3C.7 8.7 0 10.3 0 12s.7 3.3 1.9 5.7l3.7-2.9z"
                />
                <path
                  fill="#34A853"
                  d="M12 23c3.2 0 6-1.1 8-3l-3.7-2.9c-1.1.7-2.5 1.2-4.3 1.2-3 0-5.5-2.2-6.4-5.2L1.9 16C3.7 19.7 7.5 23 12 23z"
                />
              </svg>

              <span>Continue with Google</span>

              {/* Invisible Google OAuth Trigger Overlay */}
              <div className="absolute inset-0 opacity-0 cursor-pointer pointer-events-auto">
                <GoogleLogin
                  onSuccess={handleSuccess}
                  onError={() => setError("Google Login popup failed or was closed.")}
                  hosted_domain="hua.gr"
                  theme="outline"
                  shape="pill"
                  text="continue_with"
                />
              </div>
            </div>

            {error && (
              <div className="mt-4 text-[#C84B5E] text-[clamp(0.75rem,0.85vw,0.875rem)] bg-black/40 border border-[#C84B5E]/30 px-[clamp(0.875rem,1.2vw,1.25rem)] py-[clamp(0.5rem,0.8vh,0.75rem)] rounded-xl max-w-sm backdrop-blur-md">
                {error}
                <p className="mt-2 text-[0.7rem] opacity-80">
                  Developer Note: Make sure <code className="bg-white/10 px-1 py-0.5 rounded">http://192.168.1.203:3000</code> is added to your OAuth <strong>Authorized JavaScript origins</strong> in Google Cloud Console.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* RIGHT SECTION (Interactive Room 4.9 Illustration Vertically Centered with clamp padding) */}
      <div className="relative z-10 hidden lg:flex w-[50%] h-full items-center justify-center p-[clamp(2rem,4vw,4rem)]">
        <Room49Illustration />
      </div>

    </div>
  );
}